/**
     * HTTP header names
     */
    public static final String HEADER_NAME_TOOK_NANOS = "Took-nanos";

private void checkDelimiter() {
        if (mediaType != CSV && restRequest.hasParam(URL_PARAM_DELIMITER)) {
            String message = String.format(
                Locale.ROOT,
                "parameter: [%s] can only be used with the format [%s] for request [%s]",
                URL_PARAM_DELIMITER,
                CSV.queryParameter(),
                restRequest.path()
            );
            throw new IllegalArgumentException(message);
        }
    }

/**
     * Async query get API does not have an EsqlQueryRequest, store the async ID as an alternative
     */
    public EsqlResponseListener(RestChannel channel, RestRequest restRequest) {
        super(channel);

        this.channel = channel;
        this.restRequest = restRequest;
        this.esqlQueryOrId = restRequest.param("id");
        this.mediaType = EsqlMediaTypeParser.getResponseMediaType(restRequest);

        checkDelimiter();
    }

static Map<String, Object> runEsql(
        RequestObjectBuilder requestObject,
        AssertWarnings assertWarnings,
        Mode mode,
        @Nullable String format,
        @Nullable Character delimiter
    ) throws IOException {
        if (mode == ASYNC) {
            return runEsqlAsync(requestObject, assertWarnings, format, delimiter);
        } else {
            return runEsqlSync(requestObject, assertWarnings, format, delimiter);
        }
    }

if (mode == ASYNC) {
